from collections import deque

def components(g, color):
    R,C=len(g),len(g[0]); seen=set(); out=[]
    for r in range(R):
      for c in range(C):
       if g[r][c]==color and (r,c) not in seen:
        st=[(r,c)]; seen.add((r,c)); comp=[]
        while st:
         x,y=st.pop(); comp.append((x,y))
         for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
          a,b=x+dx,y+dy
          if 0<=a<R and 0<=b<C and g[a][b]==color and (a,b) not in seen:
           seen.add((a,b)); st.append((a,b))
        out.append(comp)
    return out

def hole_count(comp):
    rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    cells=set(comp); zeros={(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1)}-(cells)
    holes=0
    while zeros:
        seed=zeros.pop(); q=[seed]; group=[seed]; exterior=False
        while q:
            r,c=q.pop()
            if r in (r0,r1) or c in (c0,c1): exterior=True
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                p=(r+dr,c+dc)
                if p in zeros: zeros.remove(p); q.append(p); group.append(p)
        if not exterior: holes+=1
    return holes

def transform(grid):
    g=[row[:] for row in grid]
    mapping={}
    for color in set(sum(grid,[]))-{0,5,1}:
        for comp in components(grid,color): mapping[hole_count(comp)]=color
    for comp in components(grid,5):
        n=hole_count(comp)
        if n in mapping:
            for r,c in comp:g[r][c]=mapping[n]
    return g
